void Player::callback(void* userdata, Uint8* out, int len) noexcept {
    if (len <= 0) return;
    auto* self = static_cast<Player*>(userdata);
    self->voice_.render(out, static_cast<std::size_t>(len));
}

bool Player::replace(Pcm16&& clip) noexcept {
    // Validate before touching the old clip so a failed call preserves it.
    if (dev_ == 0) return false;
    if (clip.layout().frames == 0) return false;
    if (clip.rate() != rate_ || clip.channels() != channels_) return false;
    if (!audio_pcm::layout_s16(1, clip.channels(), clip.rate()).has_value())
        return false;

    // Transfer ownership under the lock; free the old PCM after unlocking.
    // Pcm16 moves without allocation or exceptions.
    std::optional<Pcm16> retired;
    {
        DeviceLock lock(dev_);
        voice_.stop();
        retired.swap(clip_);             // displace old PCM under the lock
        clip_.emplace(std::move(clip));  // install new PCM under the lock
    }
    return true;  // `retired` destructs here, after unlock
}

void Player::unload() noexcept {
    if (dev_ == 0) return;
    // Pause first so the real device cannot enter the callback while we mutate.
    SDL_PauseAudioDevice(dev_, 1);

    // Retired outside the lock scope: the old PCM buffer is destroyed only
    // after DeviceLock runs SDL_UnlockAudioDevice.
    std::optional<Pcm16> retired;
    {
        DeviceLock lock(dev_);
        voice_.stop();
        retired.swap(clip_);
    }
    // `retired` destructs here, i.e. the old PCM deallocation happens post-unlock.
}

void audio_unload_sound(AudioHandle h)
{
    if (!s_initialized) return;
    if (h <= 0 || h >= (int)s_sounds.size()) return;

    // Disconnect every reader under the lock; release storage after unlocking.
    std::vector<int16_t> retired;
    {
        std::lock_guard<std::mutex> lk(s_mu);
        if (s_bgm.handle == h) s_bgm = {};
        if (s_currentMusic == h) s_currentMusic = 0;
        for (auto& v : s_sfx) if (v.handle == h) v = {};
        retired.swap(s_sounds[h].pcm);
        s_sounds[h].valid = false;
    }
}

